#include <stdio.h>
#include <stdlib.h>

typedef struct {
    long long start;
    long long finish;
    long long profit;
} Job;

static int compare(const void *a, const void *b) {
    const Job *j1 = (const Job *)a;
    const Job *j2 = (const Job *)b;
    if (j1->finish != j2->finish) {
        return (j1->finish < j2->finish) ? -1 : 1;
    }
    return (j1->start < j2->start) ? -1 : 1;
}

static int find_last_compatible(Job jobs[], int i) {
    int low = 0, high = i - 1;
    int res = -1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (jobs[mid].finish <= jobs[i].start) {
            res = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return res;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    Job *jobs = (Job *)malloc(n * sizeof(Job));
    if (!jobs) return 1;

    for (int i = 0; i < n; i++) {
        scanf("%lld %lld %lld", &jobs[i].start, &jobs[i].finish, &jobs[i].profit);
    }

    qsort(jobs, n, sizeof(Job), compare);

    long long *dp = (long long *)malloc(n * sizeof(long long));
    if (!dp) return 1;

    dp[0] = jobs[0].profit;
    for (int i = 1; i < n; i++) {
        long long incl = jobs[i].profit;
        int l = find_last_compatible(jobs, i);
        if (l != -1) {
            incl += dp[l];
        }
        dp[i] = (incl > dp[i - 1]) ? incl : dp[i - 1];
    }

    printf("%lld\n", dp[n - 1]);

    free(jobs);
    free(dp);
    return 0;
}

