    int *dp = (int *)calloc(target + 1, sizeof(int));
    if (!dp) return 1;

    dp[0] = 1;
    for (int i = 0; i < n; i++) {
        int x = nums[i];
        for (int j = target; j >= x; j--) {
            if (dp[j - x]) {
                dp[j] = 1;
            }
        }
    }

    if (dp[target]) {
        printf("YES\n");
    } else {
        printf("NO\n");
    }

    free(dp);
